package dev.rodrigo.media3editor;

import android.net.Uri; import android.os.*; import android.widget.*; import androidx.activity.ComponentActivity; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.media3.common.MediaItem; import androidx.media3.common.Effect; import androidx.media3.effect.ScaleAndRotateTransformation; import androidx.media3.transformer.*; import java.io.File; import java.util.*;

@androidx.media3.common.util.UnstableApi
public class MainActivity extends ComponentActivity {
 private TextView status; private CheckBox mute,rotate; private SeekBar scale; private Uri input; private Transformer transformer; private final Handler handler=new Handler(Looper.getMainLooper());
 private final ActivityResultLauncher<String[]> picker=registerForActivityResult(new ActivityResultContracts.OpenDocument(),uri->{if(uri!=null){input=uri;getContentResolver().takePersistableUriPermission(uri,android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION);status.setText("Input: "+uri);}});
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);mute=findViewById(R.id.mute);rotate=findViewById(R.id.rotate);scale=findViewById(R.id.scale);findViewById(R.id.pick).setOnClickListener(v->picker.launch(new String[]{"video/*"}));findViewById(R.id.export).setOnClickListener(v->exportVideo());findViewById(R.id.cancel).setOnClickListener(v->{if(transformer!=null){transformer.cancel();status.setText("Export cancelled");}});}
 private void exportVideo(){if(input==null){status.setText("Pick a video first");return;}float s=Math.max(0.25f,scale.getProgress()/100f);List<Effect> videoEffects=new ArrayList<>();videoEffects.add(new ScaleAndRotateTransformation.Builder().setScale(s,s).setRotationDegrees(rotate.isChecked()?90f:0f).build());Effects effects=new Effects(Collections.emptyList(),videoEffects);EditedMediaItem item=new EditedMediaItem.Builder(MediaItem.fromUri(input)).setRemoveAudio(mute.isChecked()).setEffects(effects).build();File dir=getExternalFilesDir(Environment.DIRECTORY_MOVIES);if(dir==null){status.setText("Movies directory unavailable");return;}File out=new File(dir,"edited-"+System.currentTimeMillis()+".mp4");transformer=new Transformer.Builder(this).addListener(new Transformer.Listener(){@Override public void onCompleted(Composition composition,ExportResult result){status.setText("Done: "+out.getAbsolutePath()+"\nSize: "+result.fileSizeBytes+" bytes");transformer=null;}@Override public void onError(Composition composition,ExportResult result,ExportException exception){status.setText("Export error: "+exception.getMessage());transformer=null;}}).build();try{transformer.start(item,out.getAbsolutePath());status.setText("Export started…");pollProgress();}catch(Exception e){status.setText("Cannot start export: "+e.getMessage());transformer=null;}}
 private void pollProgress(){handler.postDelayed(new Runnable(){@Override public void run(){Transformer t=transformer;if(t==null)return;ProgressHolder h=new ProgressHolder();int state=t.getProgress(h);if(state==Transformer.PROGRESS_STATE_AVAILABLE)status.setText("Export progress: "+h.progress+"%");if(state!=Transformer.PROGRESS_STATE_NOT_STARTED)handler.postDelayed(this,500);}},500);}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(transformer!=null)transformer.cancel();super.onDestroy();}
}